import java.util.*;public class Notice{private final String title;private final List<String> targets;public Notice(String t,List<String> d){if(t==null||t.trim().isEmpty()||d==null||d.isEmpty())throw new IllegalArgumentException("At least one target department is required");title=t;targets=new ArrayList<>();for(String x:d)if(x!=null&&!x.trim().isEmpty()&&!targets.contains(x))targets.add(x);if(targets.isEmpty())throw new IllegalArgumentException("At least one target department is required");}public String getTitle(){return title;}public List<String> getTargetDepartments(){return Collections.unmodifiableList(targets);}}